`,d.jsx(o.li,{children:"The date and time of the class, with a calendar icon to the left"}),`
`,d.jsx(o.li,{children:"The difficulty level of the class, with a gauge icon to the left"}),`
`,d.jsx(o.li,{children:"The class name"}),`
`,d.jsx(o.li,{children:"The instructor name"}),`
